import React from 'react';
export function InternalPoints({points=[],chapters,onChange}){const update=(id,patch)=>onChange(points.map(p=>p.id===id?{...p,...patch}:p));return <details><summary>内部关键点 · {points.length}</summary><p className="muted">关键点固定在指定章节或故事坐标。移动整张剧情卡不会平移这些位置；关系变化仍在专门入口编辑。</p>{points.map(p=><section className="structure-entry" key={p.id}><label>关键点名称<input value={p.title||''} placeholder={p.relationships?.length?'关系变化点':'例如：发现线索'} onChange={e=>update(p.id,{title:e.target.value})}/></label>{p.relationships?.length?<small>包含 {p.relationships.length} 条关系变化，请从“管理节点”调整位置。</small>:<><label>章节<select value={p.location?.narration?.chapterId||''} onChange={e=>update(p.id,{location:{...p.location,narration:e.target.value?{chapterId:e.target.value,offset:p.location?.narration?.offset||0}:null}})}><option value="">暂不安排</option>{chapters.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></label>{p.location?.narration&&<label>章内位置（%）<input type="number" min="0" max="99" value={Math.round(p.location.narration.offset*100)} onChange={e=>update(p.id,{location:{...p.location,narration:{...p.location.narration,offset:Number(e.target.value)/100}}})}/></label>}<label>故事坐标<input type="number" step="any" value={p.location?.story??''} onChange={e=>update(p.id,{location:{...p.location,story:e.target.value===''?null:Number(e.target.value)}})}/></label><button type="button" onClick={()=>onChange(points.filter(x=>x.id!==p.id))}>移除关键点</button></>}</section>)}<button type="button" onClick={()=>onChange([...points,{id:crypto.randomUUID(),title:'',order:points.length,location:{},relationships:[]}])}>＋ 添加关键点</button></details>;}
